# 此文件验证一个部署格对应多条不同 ID 路线时会被拒绝。
[map]
id=test_map
name=重复部署路线测试
width=7
height=5
row_0=#######
row_1=#X...B#
row_2=#.....#
row_3=#A...Y#
row_4=#######

[route:a_lane]
side=A
start=1,3
points=1,3;2,3;3,3;4,3;5,3

[route:a_lane_copy]
side=A
start=1,3
points=1,3;2,3;3,3;4,3;5,3

[route:b_lane]
side=B
start=5,1
points=5,1;4,1;3,1;2,1;1,1
